import{_ as s,o as a,c as o,a3 as r}from"./chunks/framework.I6s8z2kk.js";const p=JSON.parse('{"title":"Users and roles","description":"","frontmatter":{},"headers":[],"relativePath":"user/admin/users-roles.md","filePath":"user/admin/users-roles.md"}'),t={name:"user/admin/users-roles.md"};function n(i,e,l,d,c,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="users-and-roles" tabindex="-1">Users and roles <a class="header-anchor" href="#users-and-roles" aria-label="Permalink to &quot;Users and roles&quot;">​</a></h1><h2 id="system-users" tabindex="-1">System users <a class="header-anchor" href="#system-users" aria-label="Permalink to &quot;System users&quot;">​</a></h2><p><strong>Users</strong> lists platform staff. Create a user, assign <strong>roles</strong>, and deactivate or delete them. A deleted user can be <strong>restored</strong>.</p><ul><li>Inactive users cannot sign in and are refused everywhere.</li><li>You can only manage users if you have the matching permission.</li></ul><h2 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h2><p>A role is a named set of permissions, such as &quot;Support&quot; or &quot;Finance&quot;. Create roles under <strong>Roles</strong> and tick the permissions each one needs. A user gets the permissions of all their roles.</p><p>Built-in roles are protected and cannot be edited or deleted.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Permissions are named <code>area.action</code>, for example <code>centers.view_any</code>, <code>promotions.activate</code>, <code>fees.manage</code>, <code>payouts.manage</code>, <code>analytics.view</code> and <code>api_docs.view</code>. Each area of the panel only appears for people who hold its permission.</p><h2 id="activity-log" tabindex="-1">Activity log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity log&quot;">​</a></h2><p><strong>Activity log</strong> shows who changed what and when, for audit purposes.</p>',11)])])}const m=s(t,[["render",n]]);export{p as __pageData,m as default};
